llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C38"],
      "claim": "Niraparib absolute oral bioavailability was 72.7% in six human patients after a 300 mg oral dose versus IV 14C-niraparib, well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "Fenspiride absolute oral bioavailability was 90 (9)% in 12 healthy volunteers after an 80 mg slow-release tablet versus IV, well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Ziprasidone absolute mean oral bioavailability was about 60% in healthy volunteers after a single 20 mg oral dose in the fed state, above the 20% threshold.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All informative transferred numeric records in ordinary oral conditions are above the 20% threshold (27–90%), supporting high oral bioavailability; low values are from altered conditions or inconsistent groupings and are discounted.",
  "evidence_gaps": [
    "Molecule 8 groups records for stavudine and didanosine/ddA under one label; this provenance conflict was discounted.",
    "Some low values (didanosine 19% in children with antacid; sildenafil 2.78% enteral in infants) come from altered conditions or routes and were discounted.",
    "Gaboxadol evidence is qualitative ('high') without a numeric absolute bioavailability value."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

